pub(crate) fn sprite_pixels(side: Side, role: Role) -> &'static [u8; SPRITE_BYTES] {
    match (side, role) {
        (Side::White, Role::King) => &WHITE_KING,
        (Side::White, Role::Queen) => &WHITE_QUEEN,
        (Side::White, Role::Rook) => &WHITE_ROOK,
        (Side::White, Role::Bishop) => &WHITE_BISHOP,
        (Side::White, Role::Knight) => &WHITE_KNIGHT,
        (Side::White, Role::Pawn) => &WHITE_PAWN,
        (Side::Black, Role::King) => &BLACK_KING,
        (Side::Black, Role::Queen) => &BLACK_QUEEN,
        (Side::Black, Role::Rook) => &BLACK_ROOK,
        (Side::Black, Role::Bishop) => &BLACK_BISHOP,
        (Side::Black, Role::Knight) => &BLACK_KNIGHT,
        (Side::Black, Role::Pawn) => &BLACK_PAWN,
    }
}
